import { existsSync, readFileSync, unlinkSync, writeFileSync } from 'node:fs'
import { dirname, posix, resolve } from 'node:path'

import type { LayoutImport } from './layouts.js'

const header =
  '// Generated by fondu. Typechecks the components of explicit layout chains. Commit it; do not edit.\n'

/** A plain .ts file: skipLibCheck must not hide these assertions. Check the component imports, not an MDX
 * module's opaque TS declaration. This file is never imported at runtime and isn't needed without an override. */
export function writeLayoutChecks(routes: string, declarations: Map<string, LayoutImport[]>) {
  const path = resolve(dirname(routes), 'fondu.layouts.gen.ts')
  const previous = existsSync(path) ? readFileSync(path, 'utf8') : undefined
  const lines: string[] = []
  for (const file of [...declarations.keys()].sort()) {
    for (const { source, name } of declarations.get(file)!) {
      const spec = source.startsWith('.')
        ? './' + posix.join('routes', posix.dirname(file), source)
        : source
      lines.push(
        `  // routes/${file}\n  Layout<typeof import(${JSON.stringify(spec)})[${JSON.stringify(name)}]>,`,
      )
    }
  }
  if (!lines.length) {
    if (previous?.startsWith(header)) unlinkSync(path)
    return
  }
  if (previous !== undefined && !previous.startsWith(header))
    throw new Error('fondu: app/fondu.layouts.gen.ts is reserved for generated layout checks')
  const text = `${header}import type { ComponentType, ReactNode } from 'react'\n\ntype Layout<T extends ComponentType<{ children: ReactNode }>> = T\nexport type Layouts = [\n${lines.join('\n')}\n]\n`
  if (previous !== text) writeFileSync(path, text)
}
